import { CommonModule } from '@angular/common';
import { Component, inject, signal, viewChild } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { RouterModule } from '@angular/router';
import {
  IonButton,
  IonButtons,
  IonContent,
  IonHeader,
  IonItem,
  IonList,
  IonMenuToggle,
  IonNote,
  IonSearchbar,
  IonTitle,
  IonToolbar,
  ViewWillEnter,
  IonSpinner,
} from '@ionic/angular/standalone';
import {
  catchError,
  filter,
  firstValueFrom,
  from,
  map,
  merge,
  shareReplay,
  startWith,
  Subject,
  switchMap,
  tap,
  of,
} from 'rxjs';
import { getAllBooks } from 'supabase/functions/_shared/book';
import { titleCase } from 'title-case';
import {
  BibleId,
  defaultBible,
} from '../../../supabase/functions/_shared/bibles';
import { getSearchRoutePath } from '../app.routes';
import { AlertService } from '../common/alert/alert.service';
import { BiblesService } from '../common/bibles/bibles.service';
import { MenuToggleComponent } from '../common/menu/menu-toggle.component';
import { ResultsComponent } from '../common/results/results.component';
import { LocalStorageService } from '../common/storage/local-storage.service';
import { SupabaseService } from '../common/supabase/supabase.service';
import { TimerService } from '../common/timer/timer.service';
import { SkeletonCardComponent } from '../common/verse/skeleton-card/skeleton-card.component';
import { Tag, Verse } from '../common/verse/verse';
import { SupabaseClient } from '@supabase/supabase-js';
import { Database } from 'supabase/types/supabase';
import { parseBibleReference } from './parse';

const BIBLE_BOOKS = getAllBooks();

export interface Bible {
  id: string;
  name: string;
  abbreviation: string;
  description: string | null;
  source: 'private' | 'api.bible';
}

@Component({
  selector: 'app-search',
  templateUrl: './search.page.html',
  styleUrls: ['./search.page.scss'],
  imports: [
    IonSpinner,
    IonButton,
    IonButtons,
    IonContent,
    IonItem,
    IonList,
    IonToolbar,
    IonHeader,
    IonTitle,
    IonSearchbar,
    CommonModule,
    IonNote,
    ReactiveFormsModule,
    ResultsComponent,
    SkeletonCardComponent,
    IonMenuToggle,
    RouterModule,
    MenuToggleComponent,
  ],
})
export class SearchPage implements ViewWillEnter {
  searchbar = viewChild<IonSearchbar>('searchbar');

  private supabaseService = inject(SupabaseService);
  private supabaseClient = inject<SupabaseClient<Database>>(SupabaseClient);
  private localStorage = inject(LocalStorageService);
  private alertService = inject(AlertService);
  private biblesService = inject(BiblesService);
  private timerService = inject(TimerService);

  private refreshResults$ = new Subject<{ query: string | null | undefined }>();
  private tagRefreshTrigger$ = new Subject<void>();

  readonly versesRoute = getSearchRoutePath('verse');
  controlKnobsIcon = 'node_modules/openmoji/color/svg/1F39B.svg'; // 🎛️ Control Knobs

  loading = signal(false);
  lookupError = signal('');
  showSuggestions = signal(false);

  formGroup = inject(FormBuilder).group({
    query: [
      '',
      [Validators.required, Validators.pattern(/(.*)\s*[0-9]+(:[0-9]+)?\s*$/)],
    ],
  });

  filteredBooks$ = this.formGroup.controls.query.valueChanges.pipe(
    startWith(''),
    map((query) => {
      if (
        !query ||
        query.includes(':') ||
        /\d/.test(query.split(' ').pop() || '')
      ) {
        return [];
      }
      const lowerCaseQuery = query.toLowerCase();
      return BIBLE_BOOKS.filter((book) =>
        book.toLowerCase().startsWith(lowerCaseQuery)
      ).map((book) => titleCase(book));
    }),
    shareReplay(1)
  );

  results$ = merge(
    // Tag refresh trigger - always fetches fresh tags when view enters
    this.tagRefreshTrigger$.pipe(
      switchMap(() => from(this.enrichVersesWithTags(this.supabaseService.getSearches())))
    ),
    merge(this.formGroup.valueChanges, this.refreshResults$).pipe(
      this.timerService.debounceTime(1000),
      tap(() => this.lookupError.set('')),
      filter((value: any) => Boolean(value.query && this.formGroup.valid)),
      map((value: any) => parseBibleReference(value.query!.trim().replace(/\s+/g, ' '))),
      filter((result) => result !== null),
      tap(() => this.loading.set(true)),
      switchMap(async (result) => {
        const { book, chapter, verses: searchVerses } = result;
        const start_verse =
          searchVerses === 'ALL' ? 1 : Number(searchVerses.at(0)!);
        const end_verse =
          searchVerses === 'ALL' ? 999 : Number(searchVerses.at(-1));

        const bibleId =
          (this.localStorage.getItem('selected-bible-id') as BibleId) ||
          defaultBible.id;

        const searchResult = await this.supabaseService.searchVerses(
          bibleId,
          book,
          chapter,
          start_verse,
          end_verse
        );

        if (!searchResult || searchResult?.error) {
          this.lookupError.set(
            this.normalizeErrorMessage(
              searchResult?.error || 'An error occurred'
            )
          );
          return this.enrichVersesWithTags(this.supabaseService.getSearches());
        }

        return this.enrichVersesWithTags(Promise.resolve(searchResult));
      }),
      catchError((error: unknown) => {
        this.lookupError.set(
          this.normalizeErrorMessage(
            error instanceof Error ? error.message : 'An error occurred'
          )
        );
        return from(
          this.enrichVersesWithTags(this.supabaseService.getSearches())
        );
      })
    ),
    from(this.enrichVersesWithTags(this.supabaseService.getSearches()))
  ).pipe(
    tap(() => this.loading.set(false)),
    shareReplay(1)
  );

  async ionViewWillEnter() {
    // Always trigger tag refresh when view enters to ensure tags are up-to-date
    // This is especially important when tags are modified on other pages (e.g., favorites page)
    this.tagRefreshTrigger$.next();
    
    // Also trigger the normal refresh mechanism
    const currentQuery = this.formGroup.value.query;
    this.refreshResults$.next({ query: currentQuery });
  }

  handleInput(event: any) {
    const query = event.target.value || '';
    this.formGroup.controls.query.setValue(query, { emitEvent: true });
    this.showSuggestions.set(true);
  }

  async selectBook(book: string) {
    this.formGroup.controls.query.setValue(book + ' ', { emitEvent: true });
    this.showSuggestions.set(false);
    await firstValueFrom(this.timerService.timer(150)); // Wait before focusing the searchbar
    const searchbar = this.searchbar();
    if (!searchbar) {
      return;
    }
    const value = searchbar.value;
    searchbar.setFocus();
    searchbar.value = '';
    searchbar.value = value;
  }

  async hideSuggestionsWithDelay() {
    await firstValueFrom(this.timerService.timer(150));
    this.showSuggestions.set(false);
  }

  async presentAlert() {
    const { data: bibles, error } =
      await this.biblesService.getAvailableBibles();

    if (error) {
      return this.alertService.createNotice({
        message: error.message,
        duration: 5000,
        positionAnchor: 'footer',
      });
    }

    if (!bibles?.length) {
      return this.alertService.createNotice({
        message: 'No Bible versions available',
        duration: 5000,
        positionAnchor: 'footer',
      });
    }

    return this.alertService.presentAlert({
      header: 'Select Bible Version',
      buttons: [
        {
          text: 'Cancel',
          role: 'cancel',
        },
        {
          text: 'OK',
          role: 'confirm',
          handler: (value: string) => {
            this.localStorage.setItem('selected-bible-id', value);
            this.refreshResults$.next({ query: this.formGroup.value.query });
          },
        },
      ],
      inputs: this.createAlertInputs(bibles),
    });
  }

  private createAlertInputs(bibles: Bible[]) {
    const selectedBibleId =
      this.localStorage.getItem('selected-bible-id') || defaultBible.id;

    return bibles.map((bible) => ({
      label: bible.name,
      type: 'radio' as const,
      value: bible.id,
      checked: bible.id === selectedBibleId,
    }));
  }

  /**
   * Enriches verses with tags for favorited verses.
   * Fetches tags from the database for any verses that are favorited.
   * Always fetches fresh tags to ensure data is up-to-date.
   */
  private async enrichVersesWithTags(
    searchResultPromise: Promise<{ results: Verse[]; error?: string }>
  ): Promise<{ results: Verse[]; error?: string }> {
    const searchResult = await searchResultPromise;
    
    if (!searchResult.results || searchResult.results.length === 0) {
      return searchResult;
    }

    // Filter to only favorited verses that have IDs
    const favoritedVerses = searchResult.results.filter(
      (verse) => verse.is_favorite && verse.id
    );

    if (favoritedVerses.length === 0) {
      // Return results with empty tags array for non-favorited verses
      return {
        ...searchResult,
        results: searchResult.results.map((verse) => ({
          ...verse,
          tags: [],
        })),
      };
    }

    // Fetch tags for all favorited verses
    // Always fetch fresh tags - Supabase queries are not cached by default
    const verseIds = favoritedVerses.map((v) => v.id!);
    const { data: verseTags } = await this.supabaseClient
      .from('verse_tags')
      .select('verse_id, tags(*)')
      .in('verse_id', verseIds);

    // Create a map of verse_id to tags
    const tagsByVerseId = new Map<number, Tag[]>();
    if (verseTags) {
      for (const vt of verseTags) {
        const existing: Tag[] = tagsByVerseId.get(vt.verse_id) || [];
        if (vt.tags) {
          // Handle both single object and array cases
          const tags = Array.isArray(vt.tags) ? vt.tags : [vt.tags];
          existing.push(...(tags as Tag[]));
        }
        tagsByVerseId.set(vt.verse_id, existing);
      }
    }

    // Merge tags into verses - always create new objects to ensure change detection works
    const enrichedResults = searchResult.results.map((verse) => {
      if (verse.is_favorite && verse.id) {
        const verseTags = tagsByVerseId.get(verse.id) || [];
        return {
          ...verse,
          tags: [...verseTags], // Create new array to ensure change detection
        };
      }
      // Even for non-favorited verses, ensure tags array exists for consistency
      return {
        ...verse,
        tags: verse.tags || [],
      };
    });

    // Always return a new object to ensure change detection works
    return {
      ...searchResult,
      results: enrichedResults,
    };
  }

  private normalizeErrorMessage(message: string) {
    let normalizedMessage = message;

    if (message === 'Param: search.book is required') {
      normalizedMessage = 'Please enter the name of a Bible book';
    }

    if (message === 'Param: search.chapter is required') {
      normalizedMessage = 'Please enter a chapter number';
    }

    if (message === 'Param: search.verse is required') {
      normalizedMessage = 'Please enter a verse number';
    }

    if (
      message ===
      'Param: search.start_verse is required, must be greater than 0, and must be less than 999'
    ) {
      normalizedMessage = 'Please enter a verse or verse range';
    }

    if (
      message ===
      'Param: search.end_verse is required, must be greater than 0, and must be less than 999'
    ) {
      normalizedMessage = 'Please enter a verse or verse range';
    }

    return normalizedMessage;
  }
}
